function ontwerpPrompt(g) {
  return `${REGELS}
OPDRACHT — ontwerp NIEUWE handelsassen voor **${g.naam}** voor golf 7 van M31 ("meer stromen op de bol"). Na golf 6 staan er 182 gemeten ketens over 14 grondstoffen (v1 had 578 stromen); golf 7 is een grote ronde die alle veertien grondstoffen (nu 11–15 ketens elk) verder aanvult.
${g.naam} staat al in v2 met ${g.bestaand.length} ketens: ${g.bestaand.join(', ')} (brieven in ${REPO}/v2/design/routebrieven/<id>.md, gebakken json in ${REPO}/v2/data/stroomroute-<id>.json — lees van elke bestaande brief §1). Ontwerp precies ${g.max} NIEUWE ketens (prioriteit 1..${g.max}) plus 2 reserve-assen (prioriteit ${g.max + 1} en ${g.max + 2}) die de grootste gaten in het ${g.naam}-verhaal dichten; geen overlap met de bestaande ketens (een gedeeld been met een bestaande stroom mag, als letterlijke kopie).
EERDER AFGEWEZEN (niet opnieuw voorstellen, tenzij je het bezwaar aantoonbaar oplost en dat in "risico" uitlegt): ${g.afgewezen || 'geen'}.

Invoer:
- v1-register (CHECKLIST met natte-vinger-volumes en centroïdes, geen waarheid): ${REPO}/data/${g.v1}${g.v1brief ? ` en de v1-ontwerpbrief ${REPO}/${g.v1brief} (verhaal, knelpunten, bronnen)` : ''}.
- De sitelaag van deze grondstof: ${REPO}/v2/design/${g.sleutel}-sitelaag.md (welke sites zwaar wegen en waar de gloed al staat — een keten die bij een zware site begint of eindigt is waardevoller).
- De lichte werkwijze: ${REPO}/v2/design/routebrief-licht.md (volledig) en het gereedschap: ${REPO}/v2/design/bakhandleiding-licht.md (§1–§3 en §6).
- Aanwezige Geofabrik-extracts: ls ${REPO}/v2/build-cache/geofabrik/ (Nederlandse slugs); spoornet 1-op-1: ls ${REPO}/v2/build-cache/raw1op1/. Ontbrekend o.a.: albanie, tunesie, libie, israel, jordanie, taiwan, kenia, ethiopie, kirgizie, tadzjikistan, Midden-Amerika, us-colorado en de NO-staten van de VS — vermijd landbenen daar of maak er bewust een stippel van.

Aanwijzingen voor deze grondstof: ${g.hint}

Lever (schema):
1. Het verhaal in 3–5 zinnen en de gaten ten opzichte van de bestaande ${g.bestaand.length} ketens (welke regio's, rollen of schakels ontbreken nu op de bol).
2. De HANDELSASSEN: per keten van-site en naar-site bij naam, de benen (fase, modaliteit uit ${MODS}, van→naar, corridor bij naam, km-indicatie, gereedschap: MARNET / maak_stroombeen_weg / toets_spoorroute / AIS-graaf / maak_rivierbeen / OSM-pipeline / maak_luchtbeen / stippel), hergebruik van bestaande ankers, benodigde Geofabrik-regio's met aanwezigheid (zelf gecontroleerd met ls), of het spoornet nodig is, bij leidingen of OSM de leiding heeft (osm_leiding), jaarvolume met bron en peiljaar (eenheid ${g.eenheidHint}), het grootste risico, en 2–4 startbronnen (url's).
   - keten_id = "${g.prefix}-<van>-<naar>" in kleine letters zonder diakrieten; controleer met ls ${REPO}/v2/data/stroomroute-*.json dat het id nog niet bestaat.
   - Spreid over de wereld en over verschillende corridors en rollen (mijn → verwerker, verwerker → afnemer); niet meerdere ketens met hetzelfde begin én dezelfde zeestraat.
   - Een keten die bij een haven, terminal of verwerker ophoudt omdat de afnemer niet gedocumenteerd is, mag — de lijn eindigt waar het bewijs eindigt. Een keten van één kort been is te dun.
3. Opmerkingen: wat afwijkt van het gebruikelijke patroon.
Dit is een ONTWERP-stap: maak of wijzig geen bestanden. Wees eerlijk over onzekerheid; verzin geen sites of volumes.`
}

function toetsPrompt(g, ontwerp) {
  return `${REGELS}
OPDRACHT — toets het ketenontwerp voor **${g.naam}** (M31 golf 7) op HAALBAARHEID met het bestaande gereedschap en op INHOUDELIJKE JUISTHEID. Wees een skeptische collega: probeer elke keten af te wijzen; alleen wat je niet kunt afwijzen blijft haalbaar.

Ontwerp (JSON): ${JSON.stringify(ontwerp)}
Bestaande ${g.naam}-ketens in v2: ${g.bestaand.join(', ')}. Eerder afgewezen: ${g.afgewezen || 'geen'}.

Lees ${REPO}/v2/design/bakhandleiding-licht.md (gereedschap incl. §2 "Lucht", valkuilen) en ${REPO}/v2/design/routebrief-licht.md §1.
Per keten:
1. Kan elk been met het genoemde gereedschap gemaakt worden? Zee: ligt de haven in MARNET-bereik — draai het zeeknoop-recept uit de handleiding §2 en noteer per kade de afstand (> 5 km = haven-aanloop nodig); weg: is de Geofabrik-regio aanwezig (ls ${REPO}/v2/build-cache/geofabrik/) en is de corridor een openbare weg; spoor: dekt ${REPO}/v2/build-cache/raw1op1/ die regio; leiding: bestaat er een OSM-way (man_made=pipeline, naam/substance) — zoek hem echt op (Overpass, of osmium/pyosmium op de extract als dat snel gaat) of het wordt een stippel; lucht: vrachtterminals + bron dat het vliegt.
2. Klopt de keten inhoudelijk? Doe 1–2 snelle checks per keten op de aanname die het makkelijkst omvalt (draait de mijn/fabriek nog, is de haven de juiste, is de modaliteit juist, bestaat de afnemer, is de route actueel na sancties/staatsgrepen/sluitingen). Noteer wat je vond met url. Let op het webbudget.
3. Is het id nieuw (ls ${REPO}/v2/data/stroomroute-*.json) en overlapt de keten niet met een bestaande v2-stroom of met een andere keten in dit ontwerp? Een gedeeld been is prima als letterlijke kopie; een keten die grotendeels een bestaande stroom herhaalt is niet haalbaar.
4. Per keten: haalbaar (true/false), problemen, en een concrete, BINDENDE aanpassing als die nodig is (andere haven/corridor/afnemer, inkorten tot waar het bewijs eindigt, been als stippel). Een keten die grotendeels uit stippels zou bestaan is niet haalbaar. Wijs alleen af als de keten niet te redden is; de reserves (prioriteit > ${g.max}) toets je even streng.
Verander niets in de repo.`
}

function briefPrompt(it) {
  const g = it.g
  return `${REGELS}
OPDRACHT — schrijf de LICHTE routebrief voor keten **${it.id}** (grondstof ${g.naam}, M31 golf 7).

Invoer:
1. Het ketenontwerp (JSON): ${JSON.stringify(it.as)}
2. De haalbaarheidstoets (JSON, BINDEND — pas "aanpassing" en de "problemen" toe): ${JSON.stringify(it.toets)}
3. Werkwijze + sjabloon: ${REPO}/v2/design/routebrief-licht.md (volledig). Voorbeelden: ${REPO}/v2/design/routebrieven/nikkel-sudbury-kristiansand.md, olie-habshan-chiba.md, goud-loulo-ticino.md (met luchtbeen), en de bestaande ${g.naam}-brieven (${g.bestaand.join(', ')}).
4. Wat de bak-agent nodig heeft: ${REPO}/v2/design/bakhandleiding-licht.md §1–§3.
5. v1 als checklist en bronnenstartpunt: ${REPO}/data/${g.v1}${g.v1brief ? ` en ${REPO}/${g.v1brief}` : ''}; de sitelaag ${REPO}/v2/design/${g.sleutel}-sitelaag.json (hergebruik een site-coördinaat die daar bron-gelegd staat).

Werkwijze:
- Onderzoek met bronnen — 6–15 bronnen met url in §8. Verzin niets; wat je niet vindt wordt een open punt. Houd je aan het webbudget.
- Leg ELK anker op site-niveau met een satellietblik (python ${REPO}/v2/tools/sat_check.py; bestandsnaam met prefix ${it.id}-), of hergebruik een bestaand anker letterlijk (noem de bron-brief). Noteer in één zin wat je zag.
- Wegbenen: 3–8 via-punten óp de corridorweg in reisvolgorde (nooit in een stadscentrum), met refs, een ECHTE wegkilometer (of letterlijk "hemelsbreed X km, geen wegkm") en de Geofabrik-regio's. Spoorbenen: kop/staart op het emplacement + via-punten bij een corridorkeuze. Zeebenen: kade-/terminalanker en de afstand tot de MARNET-zeeknoop (> 5 km = haven-aanloop). Leidingbenen: naam, OSM-way-id's of -naam, en welke stukken stippel worden. Luchtbenen: de twee vrachtterminals (lat,lon + IATA), de bron dat het vliegt, en het airside-patroon.
- Schrijf de brief naar ${REPO}/v2/design/routebrieven/${it.id}.md volgens het sjabloon (§1 t/m §8; §9 leeg voor de bak-agent), ≤ ~110 regels, status "concept", stroom-id \`${it.id}\`, titel "${g.titel} · Van → Via → Naar (land)", anker-id's met prefix \`${g.anker}-\`, en "geschreven: ${DATUM} · werkwijze: licht (M31 golf 7)".
- Blijkt de keten bij het onderzoek niet te bestaan of niet te redden (afnemer bestaat niet, mijn dicht, route verboden, grotendeels stippel), schrijf dan GEEN brief, zet afgebroken=true met de reden, en vul de verplichte velden minimaal.
- Volumes: jaarvolume met bron en peiljaar, eenheid ${g.eenheidHint}.

Lever het gestructureerde eindrapport (schema). In "bak_aanwijzingen": per been het tool, de invoerpunten (lat,lon), de km, de extracts, haven-aanlopen, stippels met reden, letterlijke kopieën (bestand/functie), en per vlucht de twee vrachtterminals + de beennaam.`
}

function bakePrompt(it, brief) {
  const b = brief || {}
  const briefPad = b.brief_pad || `${REPO}/v2/design/routebrieven/${it.id}.md`
  const fn = it.id.replace(/-/g, '_')
  return `${REGELS}
OPDRACHT — BAK de stroom **${it.id}** (grondstof ${it.g.naam}) op basis van de routebrief ${briefPad}.

Lees eerst volledig: ${REPO}/v2/design/bakhandleiding-licht.md, daarna de brief, daarna in ${REPO}/v2/tools/bak_stromen.sh de functies bak_koper_grasberg, bak_olie_habshan_chiba (haven-aanloop als --stippel-geojson), bak_uranium_inkai_poti, bak_goud_loulo_ticino (luchtbeen + airside-stippel) en een functie met een leidingbeen (grep -n 'leiding|' v2/tools/bak_stromen.sh) als voorbeelden, en de functies van de bestaande ${it.g.naam}-stromen als je daar een been van kopieert.
Samenvatting van de brief: ${JSON.stringify({ keten_in_een_zin: b.keten_in_een_zin, benen: b.benen, ankers: b.ankers, via_punten: b.via_punten, bak_aanwijzingen: b.bak_aanwijzingen, extracts: b.extracts, open_punten: b.open_punten })}

STAP 0 — restanten van een eerder afgebroken poging: grep -n 'bak_${fn}' v2/tools/bak_stromen.sh; grep -n '"${it.id}-' v2/tools/maak_stroombeen_weg.py; ls v2/data/stroomroute-${it.id}.json v2/build-cache/ais/graaf/${it.id}-* 2>/dev/null; grep -n '^## 9' ${briefPad}. Bestaat er al een functie of profiel van deze stroom, dan VERVANG je die (nooit twee met dezelfde naam); complete tussenuitvoer mag je hergebruiken.
Invoegpunten: de ankerregels "# ── NIEUWE STROOMFUNCTIES HIERBOVEN INVOEGEN" in v2/tools/bak_stromen.sh en "# ── NIEUWE PROFIELEN HIERONDER INVOEGEN" in v2/tools/maak_stroombeen_weg.py; dispatch generiek (bash v2/tools/bak_stromen.sh <stroom-id>). Andere agenten bewerken dezelfde twee bestanden tegelijk: lees vlak vóór elke edit opnieuw en doe één kleine gerichte edit; faalt de edit, lees opnieuw en probeer nog eens.

${SLOTS}

STAP 1 — geometrie per been, in reisvolgorde, tussenuitvoer in v2/build-cache/ais/graaf/ met de prefix ${it.id}-:
- lucht: maak_luchtbeen.py (bakhandleiding §2 "Lucht"); airside-vrachtplatform → wegbeen tot de openbare weg + korte stippel.
- weg: profiel direct ná de ankerregel in PROFIELEN (sleutel = ${it.id}-<van>-<naar>, coördinaten (lon, lat)!), scan via het weg-slot (en het reus-slot bij een reus-extract). Ontbrekende extract → stippel met reden, niet downloaden. Via-snap > 5 km → wegklasse controleren (corridorKlassen / eindToegangPrivaat), nooit een via-punt bijschuiven om de km-toets te halen. Een via-punt dat een omweg geeft (segment-km ≫ hemelsbreed) verwijder of verplaats je naar de doorgaande weg, met een ⚠-noot.
- zee: zeeknoop per kade (handleiding §2), --been kade → kade; kade > 5 km van haar zeeknoop → haven-aanloop (timeout 300 python v2/tools/maak_havenaanloop.py …; exit 124 → rechte --stippel, geen tweede poging).
- spoor: BAKE_SUFFIX=-raw node v2/tools/toets_spoorroute.mjs … via het zwaar-slot.
- leiding/binnenvaart: zoals de handleiding; OSM-leiding doorgetrokken, ontbrekend stuk stippel met reden; gedeeld been = letterlijke kopie.

STAP 2 — functie bak_${fn}() met kopcommentaar (routebrief, ⚠-noten) direct VÓÓR de ankerregel; --marker voor ELK anker uit §3; --routebrief ${briefPad.replace(REPO + '/', '')}, --uit v2/data/stroomroute-${it.id}.json, --stroom ${it.id}, --titel "<titel uit de brief>". Draai via het zwaar-slot: bash v2/tools/bak_stromen.sh ${it.id}.

STAP 3 — toets (handleiding §5): km per gemeten landbeen tegen de brief (±15% als de brief een echte wegkm geeft), geen naad > 5 km, markers ≤ ~0,5 km van hun lijn, python v2/tools/toets_knikken.py --bestand v2/data/stroomroute-${it.id}.json, python v2/tools/toets_rechte_benen.py --min-km 5, json.load met versie 2 / punt_formaat lonlat / modaliteiten in ${MODS} / elk been ≥ 2 punten / bestand_kb. Naad > 5 km door een zee-snap → haven-aanloop en herbakken; andere afwijkingen = bevinding.

STAP 4 — §9 "Gebakken (${DATUM}, lichte werkwijze, M31 golf 7)" onderaan de brief (benen, km, markers, recept, toelichting per stippel/aanloop/vlucht/leiding, lessen) en status "gebakken" in de kop.

NIET: v2/src/*.js, v2/index.html, sitelagen, ?v=, git, bestaande stromen herbakken, andermans functies/profielen wijzigen, extracts downloaden.

Lever het eindrapport (schema), met registerregel exact: { sleutel: "${it.g.kort}-<xy>", bestand: "stroomroute-${it.id}.json", grondstof: "${it.g.sleutel}", label: "<Van> → <Naar>", aan: true, noot: "M31 · golf 7 (${DATUM}): <één zin over de keten>" } — xy = de eerste letter van het <van>- en het <naar>-deel van het stroom-id. BEZETTE SLEUTELS van deze grondstof (kies een vrije; botst xy, neem dan een derde letter): ${it.g.sleutels.join(', ')}. Faalt het bakken: gebakken=false en in "problemen" precies wat misging en wat wél op schijf staat.`
}

function keuringPrompt(it, bake) {
  const fn = it.id.replace(/-/g, '_')
  return `${REGELS}
OPDRACHT — KEUR de zojuist gebakken stroom **${it.id}** (grondstof ${it.g.naam}) onafhankelijk na. Vertrouw het rapport niet, meet zelf. Herstel alleen MECHANISCHE fouten; inhoudelijke keuzes laat je staan en rapporteer je.

Rapport van de bak-agent (JSON): ${JSON.stringify(bake)}
Bestanden: v2/data/stroomroute-${it.id}.json · bak_${fn} in v2/tools/bak_stromen.sh · brief v2/design/routebrieven/${it.id}.md · handleiding v2/design/bakhandleiding-licht.md (§2 incl. "Lucht", §5, §6).

Meet:
1. json: versie 2, punt_formaat lonlat, stroom == "${it.id}", modaliteiten in ${MODS}, elk been ≥ 2 punten, bestandsgrootte.
2. Naden met het naad-script uit handleiding §5 (volgt vertakt_van); per naad > 1 km de oorzaak.
3. Markers: afstand tot het dichtstbijzijnde lijnpunt; > 0,5 km noteren.
4. toets_knikken.py en toets_rechte_benen.py --min-km 5 (filter op deze stroom): een recht been zonder stippel (anders dan lucht) is een fout.
5. Luchtbenen (als die er zijn): "lucht", doorgetrokken, "grootcirkel" in de naam, kop/staart ≤ 0,5 km van een vrachtterminal-marker, km ≈ grootcirkel → luchtbenen_ok.
6. Wegbenen: vergelijk per wegbeen de km met de hemelsbrede afstand kop→staart; een verhouding > 1,6 zonder reden in de brief (bergen, meer, grens) is een omweg-verdenking — noteer in omweg_verdenkingen, niet repareren.
7. Stippel-aandeel: km stippel / totaal km (zonder zee en lucht mee te tellen als stippel) → stippel_aandeel_pct.
8. §9 onderaan de brief en status "gebakken"?

Herstel (alleen in deze stroom): naad > 5 km door een zee-snap → haven-aanloop, herbakken, regel in §9; ontbrekende marker uit §3 → toevoegen en herbakken; recht been zonder stippel (geen lucht) → stippel als het echt ongemeten is; vlucht als stippel → omzetten naar --been-geojson "lucht|…".
${SLOTS}
Lees bak_stromen.sh vlak vóór je edit opnieuw en wijzig uitsluitend bak_${fn}.
NIET: via-punten verschuiven om een km-toets te halen, andere stromen/functies, src/index.html/sitelagen, git.

Oordeel: "goed", "goed-met-bevindingen" of "niet-registreren" (alleen als de stroom niet laadt, grotendeels uit stippels bestaat, of een fout bevat die je niet mechanisch kunt herstellen). Lever het rapport (schema).`
}

function ketenPipeline(items) {
  return pipeline(items,
    async (it) => {
      const g = it.g
      const brief = await agent(briefPrompt(it), { label: `brief:${it.id}`, phase: 'Brieven', effort: 'high', schema: BRIEF_SCHEMA, ...OPTS })
      if (!brief || brief.afgebroken) log(`${it.id}: brief ${brief ? 'AFGEBROKEN — ' + (brief.reden_afgebroken || '') : 'ontbreekt'}`)
      return { id: it.id, grondstof: g.sleutel, toets: it.toets, brief }
    },
    async (r, it) => {
      if (!r || !r.brief || r.brief.afgebroken) return r
      const bake = await agent(bakePrompt(it, r.brief), { label: `bake:${it.id}`, phase: 'Bakken', effort: 'high', schema: BAKE_SCHEMA, ...OPTS })
      log(`${it.id}: ${bake && bake.gebakken ? 'gebakken ' + (bake.totaal_km || '?') + ' km' : 'NIET gebakken'}`)
      return { ...r, bake }
    },
    async (r, it) => {
      if (!r || !r.bake || !r.bake.gebakken) return r
      const keuring = await agent(keuringPrompt(it, r.bake), { label: `keuring:${it.id}`, phase: 'Keuring', effort: 'medium', schema: KEURING_SCHEMA, ...OPTS })
      log(`${it.id}: keuring ${keuring ? keuring.oordeel + (keuring.herbakken ? ' (hersteld)' : '') : 'ontbreekt'}`)
      return { ...r, keuring }
    },
  )
}

const ontwerpStroom = () => pipeline(GRONDSTOFFEN,
  (g) => agent(ontwerpPrompt(g), { label: `ontwerp:${g.sleutel}`, phase: 'Ontwerp', effort: 'high', schema: ONTWERP_SCHEMA, ...OPTS }),
  async (ontwerp, g) => {
    if (!ontwerp) { log(`ontwerp ${g.sleutel} mislukt — grondstof overgeslagen`); return null }
    const toets = await agent(toetsPrompt(g, ontwerp), { label: `toets:${g.sleutel}`, phase: 'Toets', effort: 'high', schema: TOETS_SCHEMA, ...OPTS })
    return { ontwerp, toets }
  },
  async (ot, g) => {
    if (!ot) return null
    const { ontwerp, toets } = ot
    const oordeel = new Map(((toets && toets.ketens) || []).map((k) => [k.keten_id, k]))
    const assen = [...(ontwerp.assen || [])].sort((a, b) => (a.prioriteit || 99) - (b.prioriteit || 99))
    const bestaand = new Set(g.bestaand)
    const gereserveerd = new Set(RESERVES.map((r) => r.id))
    const gekozen = assen.filter((a) => { const t = oordeel.get(a.keten_id); return !bestaand.has(a.keten_id) && !gereserveerd.has(a.keten_id) && (!t || t.haalbaar !== false) }).slice(0, g.max)
    const afgewezen = assen.filter((a) => !gekozen.includes(a)).map((a) => `${a.keten_id}${oordeel.get(a.keten_id) && oordeel.get(a.keten_id).haalbaar === false ? ' (afgewezen)' : ' (reserve)'}`)
    log(`${g.sleutel}: ${gekozen.length}/${g.max} ketens door — ${gekozen.map((a) => a.keten_id).join(', ')}${afgewezen.length ? ' · niet: ' + afgewezen.join(', ') : ''}${toets ? '' : ' · LET OP: toets ontbreekt'}`)
    const items = gekozen.map((a) => ({ id: a.keten_id, as: a, toets: oordeel.get(a.keten_id) || { opmerking: 'geen per-keten-oordeel gevonden', algemeen: toets && toets.algemeen }, g }))
    const ketens = await ketenPipeline(items)
    return { grondstof: g.sleutel, ontwerp, toets, afgewezen, ketens: ketens.filter(Boolean) }
  },
)

const reserveStroom = () => ketenPipeline(RESERVES.map((r) => ({ id: r.id, as: r.as, toets: r.toets, g: GBY[r.g] })))

const [ontwerpRes, reserveRes] = await parallel([ontwerpStroom, reserveStroom])
const resultaten = (ontwerpRes || []).filter(Boolean)
const reserveKetens = (reserveRes || []).filter(Boolean)

const alle = [...resultaten.flatMap((r) => r.ketens), ...reserveKetens]
const ok = alle.filter((k) => k.bake && k.bake.gebakken)
log(`klaar: ${ok.length}/${alle.length} gebakken, ${ok.filter((k) => !k.keuring || k.keuring.oordeel !== 'niet-registreren').length} registreerbaar (waarvan ${reserveKetens.filter((k) => k.bake && k.bake.gebakken).length} reserve-assen), over ${resultaten.length}/${GRONDSTOFFEN.length} grondstoffen`)
return {
  overzicht: alle.map((k) => ({
    id: k.id, grondstof: k.grondstof, reserve: reserveKetens.includes(k),
    afgebroken: !!(k.brief && k.brief.afgebroken), reden: k.brief && k.brief.afgebroken ? k.brief.reden_afgebroken : null,
    gebakken: !!(k.bake && k.bake.gebakken),
    titel: k.bake && k.bake.titel,
    registerregel: k.bake && k.bake.registerregel,
    totaal_km: k.keuring && k.keuring.totaal_km_na ? k.keuring.totaal_km_na : k.bake && k.bake.totaal_km,
    naden_max_km: k.keuring && k.keuring.naden_max_km_na != null ? k.keuring.naden_max_km_na : k.bake && k.bake.naden_max_km,
    bestand_kb: k.keuring && k.keuring.bestand_kb ? k.keuring.bestand_kb : k.bake && k.bake.bestand_kb,
    keuring: k.keuring && k.keuring.oordeel, keuring_reden: k.keuring && k.keuring.reden,
    omweg: k.keuring && k.keuring.omweg_verdenkingen, stippel_pct: k.keuring && k.keuring.stippel_aandeel_pct,
    hersteld: k.keuring && k.keuring.hersteld, problemen: k.bake && k.bake.problemen,
  })),
  afgewezen: Object.fromEntries(resultaten.map((r) => [r.grondstof, r.afgewezen])),
  resultaten,
}
